/// <summary>
/// Constructs a <c>METSupplierChangeCompletedBusinessEventContract</c>.
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <param name = "_vendAccount">Vendor Account</param>
/// <param name = "_coverageWareHouseIdList">List of warehouse ids</param>
/// <returns>An instance of <c>METSupplierChangeCompletedBusinessEventContract</c>.</returns>
public static METSupplierChangeCompletedBusinessEventContract newFromSupplierChangeCompleted(ItemId _itemId, List _coverageWhsIdVendAccountNumberList)
{
    METSupplierChangeCompletedBusinessEventContract contract = new METSupplierChangeCompletedBusinessEventContract();
    contract.initialize(_itemId, _coverageWhsIdVendAccountNumberList);
    return contract;
}

/// <summary>
/// Item query
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns>Item Id</returns>
[DataMember('Item'), BusinessEventsDataMember("@SYS123828")]
public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;

    return itemId;
}

/// <summary>
/// Get or set coverage whs id and vendor account
