/// <returns>Coverage whs id and vendor account list</returns>
[
 DataMember('CoverageWarehouseIdVendorAccountNumber'),
 DataCollection(Types::String),
 BusinessEventsDataMember("Coverage warehouse id & Vendor account number")]
public List parmCoverageWhsIdVendAccountNumberList(List _coverageWhsIdVendAccountNumberList = coverageWhsIdVendAccountNumberList)
{
    coverageWhsIdVendAccountNumberList = _coverageWhsIdVendAccountNumberList;

    return coverageWhsIdVendAccountNumberList;
}

/// <summary>
/// Initializes the data members
/// </summary>
/// <param name = "_itemId">Item Id</param>
